export function zip(files){const local=[],central=[];let offset=0;for(const[name,value]of Object.entries(files)){const nameBytes=encoder.encode(name),data=typeof value==='string'?encoder.encode(value):value,crc=crc32(data);const h=bytes(30),d=view(h);d.setUint32(0,0x04034b50,true);d.setUint16(4,20,true);d.setUint16(6,0x800,true);d.setUint32(14,crc,true);d.setUint32(18,data.length,true);d.setUint32(22,data.length,true);d.setUint16(26,nameBytes.length,true);local.push(h,nameBytes,data);const c=bytes(46),v=view(c);v.setUint32(0,0x02014b50,true);v.setUint16(4,20,true);v.setUint16(6,20,true);v.setUint16(8,0x800,true);v.setUint32(16,crc,true);v.setUint32(20,data.length,true);v.setUint32(24,data.length,true);v.setUint16(28,nameBytes.length,true);v.setUint32(42,offset,true);central.push(c,nameBytes);offset+=h.length+nameBytes.length+data.length}const c=concat(central),end=bytes(22),v=view(end);v.setUint32(0,0x06054b50,true);v.setUint16(8,Object.keys(files).length,true);v.setUint16(10,Object.keys(files).length,true);v.setUint32(12,c.length,true);v.setUint32(16,offset,true);return concat([...local,c,end])}
